//! Rectangles, slots and regular polygons expanded into ordinary sketch
//! geometry before patterns. O(generated points) expansion; each generated
//! point adds two unknowns and exactly two equations from existing
//! constraint kinds, so shapes solve like hand-drawn outlines.
use super::*;

/// Bound on points generated by all shapes of one sketch.
const MAX_SHAPE_POINTS: usize = 20_000;

impl SketchShape {
    pub fn id(&self) -> &str {
        match self {
            Self::Rectangle { id, .. }
            | Self::Slot { id, .. }
            | Self::Conic { id, .. }
            | Self::Polygon { id, .. } => id,
        }
    }

    /// Boundary entity IDs in traversal order.
    pub fn boundary(&self) -> Vec<String> {
        let id = self.id();
        match self {
            Self::Rectangle { .. } => (0..4).map(|k| format!("{id}:side{k}")).collect(),
            Self::Slot { .. } => ["right", "end_cap", "left", "start_cap"]
                .map(|part| format!("{id}:{part}"))
                .into(),
            Self::Polygon { sides, .. } => (0..*sides).map(|k| format!("{id}:side{k}")).collect(),
            Self::Conic { .. } => vec![id.to_owned()],
        }
    }

    fn generated_points(&self) -> usize {
        match self {
            Self::Rectangle { .. } => 2,
            Self::Slot { .. } => 4,
            Self::Polygon { sides, .. } => *sides as usize - 1,
            Self::Conic { .. } => 0,
        }
    }
}

fn literal(value: f64) -> ScalarExpr {
    ScalarExpr::Literal(Quantity::length(value, LengthUnit::Millimeter))
}

fn free_point(id: String, at: SketchPoint2) -> SketchPoint {
    SketchPoint {
        id,
        x: literal(at.x),
        y: literal(at.y),
        fixed: false,
    }
}

fn line(id: String, start: &str, end: &str) -> SketchLine {
    SketchLine {
        id,
        start: start.into(),
        end: end.into(),
    }
}

impl SketchDefinition {
    /// The sketch with shapes replaced by their generated geometry and
    /// constraints, and shape IDs in `profile`/`holes` replaced by their
    /// boundaries. Generated points are seeded at the exact shape for the
    /// given parameters, or at the origin when only the structure matters.
    pub(super) fn with_shapes_expanded(
        &self,
        parameters: Option<&HashMap<String, ParameterValue>>,
    ) -> Result<Self, ModelError> {
        let mut ids = HashSet::new();
        let mut generated = 0usize;
        for shape in &self.shapes {
            if shape.id().is_empty() || shape.id().contains(':') || !ids.insert(shape.id()) {
                return Err(ModelError::new(
                    "sketch shape ids must be nonempty, unique and free of ':'",
                ));
            }
            if let SketchShape::Polygon { sides, .. } = shape
                && !(3..=1000).contains(sides)
            {
                return Err(ModelError::new(format!(
                    "polygon '{}' needs 3 to 1000 sides",
                    shape.id()
                )));
            }
            generated += shape.generated_points();
        }
        if generated > MAX_SHAPE_POINTS {
            return Err(ModelError::new(format!(
                "sketch shapes generate {generated} points; the limit is {MAX_SHAPE_POINTS}"
            )));
        }
        let known = self
            .points
            .iter()
            .map(|p| (p.id.as_str(), p))
            .collect::<HashMap<_, _>>();
        let seed = |id: &str| -> Result<SketchPoint2, ModelError> {
            let point = known.get(id).ok_or_else(|| {
                ModelError::new(format!("sketch shape refers to unknown point '{id}'"))
            })?;
            Ok(match parameters {
                Some(parameters) => SketchPoint2 {
                    x: scalar(&point.x, parameters, Dimension::Length)?,
                    y: scalar(&point.y, parameters, Dimension::Length)?,
                },
                None => SketchPoint2 { x: 0.0, y: 0.0 },
            })
        };
        let value = |expression: &ScalarExpr, dimension| -> Result<f64, ModelError> {
            parameters.map_or(Ok(0.0), |parameters| {
                scalar(expression, parameters, dimension)
            })
        };
        let mut result = self.clone();
        result.shapes.clear();
        for shape in &self.shapes {
            let id = shape.id();
            let name = |part: &str| format!("{id}:{part}");
            match shape {
                SketchShape::Rectangle {
                    first,
                    opposite,
                    angle,
                    ..
                } => {
                    let (a, c) = (seed(first)?, seed(opposite)?);
                    let theta = angle
                        .as_ref()
                        .map_or(Ok(0.0), |angle| value(angle, Dimension::Scalar))?;
                    let (u, v) = ((theta.cos(), theta.sin()), (-theta.sin(), theta.cos()));
                    let (dx, dy) = (c.x - a.x, c.y - a.y);
                    let along = dx * u.0 + dy * u.1;
                    let across = dx * v.0 + dy * v.1;
                    result.points.extend([
                        free_point(
                            name("corner1"),
                            SketchPoint2 {
                                x: a.x + along * u.0,
                                y: a.y + along * u.1,
                            },
                        ),
                        free_point(
                            name("corner3"),
                            SketchPoint2 {
                                x: a.x + across * v.0,
                                y: a.y + across * v.1,
                            },
                        ),
                    ]);
                    let corners = [
                        first.clone(),
                        name("corner1"),
                        opposite.clone(),
                        name("corner3"),
                    ];
                    let sides = (0..4)
                        .map(|k| name(&format!("side{k}")))
                        .collect::<Vec<_>>();
                    for k in 0..4 {
                        result.lines.push(line(
                            sides[k].clone(),
                            &corners[k],
                            &corners[(k + 1) % 4],
                        ));
                    }
                    match angle {
                        None => result.constraints.extend([
                            SketchConstraint::Horizontal {
                                line: sides[0].clone(),
                            },
                            SketchConstraint::Vertical {
                                line: sides[1].clone(),
                            },
                            SketchConstraint::Horizontal {
                                line: sides[2].clone(),
                            },
                            SketchConstraint::Vertical {
                                line: sides[3].clone(),
                            },
                        ]),
                        Some(angle) => result.constraints.extend([
                            SketchConstraint::LineAngle {
                                line: sides[0].clone(),
                                value: angle.clone(),
                            },
                            SketchConstraint::Perpendicular {
                                first: sides[0].clone(),
                                second: sides[1].clone(),
                            },
                            SketchConstraint::Parallel {
                                first: sides[2].clone(),
                                second: sides[0].clone(),
                            },
                            SketchConstraint::Perpendicular {
                                first: sides[2].clone(),
                                second: sides[3].clone(),
                            },
                        ]),
                    }
                }
                SketchShape::Slot {
                    start, end, radius, ..
                } => {
                    let (a, b) = (seed(start)?, seed(end)?);
                    let r = value(radius, Dimension::Length)?;
                    let length = (b.x - a.x).hypot(b.y - a.y).max(f64::EPSILON);
                    // Left normal of the start-to-end direction.
                    let n = (-(b.y - a.y) / length, (b.x - a.x) / length);
                    let offset = |p: SketchPoint2, s: f64| SketchPoint2 {
                        x: p.x + s * r * n.0,
                        y: p.y + s * r * n.1,
                    };
                    let parts = [
                        ("start_right", offset(a, -1.0)),
                        ("end_right", offset(b, -1.0)),
                        ("end_left", offset(b, 1.0)),
                        ("start_left", offset(a, 1.0)),
                    ];
                    for (part, at) in parts {
                        result.points.push(free_point(name(part), at));
                    }
                    let [sr, er, el, sl] = parts.map(|(part, _)| name(part));
                    result
                        .lines
                        .extend([line(name("right"), &sr, &er), line(name("left"), &el, &sl)]);
                    result.arcs.extend([
                        SketchArc {
                            id: name("end_cap"),
                            center: end.clone(),
                            start: er.clone(),
                            end: el.clone(),
                            clockwise: false,
                        },
                        SketchArc {
                            id: name("start_cap"),
                            center: start.clone(),
                            start: sl.clone(),
                            end: sr.clone(),
                            clockwise: false,
                        },
                    ]);
                    for cap in ["end_cap", "start_cap"] {
                        result.constraints.push(SketchConstraint::Radius {
                            curve: name(cap),
                            value: radius.clone(),
                        });
                    }
                    for (side, cap, point) in [
                        ("right", "end_cap", &er),
                        ("left", "end_cap", &el),
                        ("left", "start_cap", &sl),
                        ("right", "start_cap", &sr),
                    ] {
                        result.constraints.push(SketchConstraint::Tangent {
                            first: name(side),
                            second: name(cap),
                            point: point.clone(),
                        });
                    }
                }
                SketchShape::Conic {
                    start,
                    control,
                    end,
                    rho,
                    ..
                } => {
                    for point in [start, control, end] {
                        seed(point)?;
                    }
                    if start == control || control == end || start == end {
                        return Err(ModelError::new(format!(
                            "conic '{id}' needs distinct start, control and end points"
                        )));
                    }
                    let rho = rho
                        .clone()
                        .unwrap_or(ScalarExpr::Literal(Quantity::scalar(0.5)));
                    if parameters.is_some() {
                        let value = value(&rho, Dimension::Scalar)?;
                        if !(value > 0.0 && value < 1.0) {
                            return Err(ModelError::new(format!(
                                "conic '{id}' rho must be in (0, 1); it is {value}"
                            )));
                        }
                    }
                    // Middle weight w = rho / (1 − rho); end weights are 1.
                    let one = ScalarExpr::Literal(Quantity::scalar(1.0));
                    let weight = ScalarExpr::Divide(
                        Box::new(rho.clone()),
                        Box::new(ScalarExpr::Subtract(Box::new(one.clone()), Box::new(rho))),
                    );
                    result.splines.push(SketchSpline {
                        id: id.to_owned(),
                        points: vec![start.clone(), control.clone(), end.clone()],
                        basis: Some(SketchBSplineBasis {
                            non_clamped: false,
                            periodic: false,
                            degree: 2,
                            knots: vec![0.0, 1.0],
                            multiplicities: vec![3, 3],
                            weights: vec![one.clone(), weight, one],
                        }),
                        endpoints: None,
                    });
                }
                SketchShape::Polygon {
                    center,
                    vertex,
                    sides,
                    ..
                } => {
                    let (c, v) = (seed(center)?, seed(vertex)?);
                    let n = *sides as usize;
                    let step = std::f64::consts::TAU / n as f64;
                    let vertices = std::iter::once(vertex.clone())
                        .chain((1..n).map(|k| name(&format!("vertex{k}"))))
                        .collect::<Vec<_>>();
                    for (k, id) in vertices.iter().enumerate().skip(1) {
                        let (sin, cos) = (step * k as f64).sin_cos();
                        let (dx, dy) = (v.x - c.x, v.y - c.y);
                        result.points.push(free_point(
                            id.clone(),
                            SketchPoint2 {
                                x: c.x + dx * cos - dy * sin,
                                y: c.y + dx * sin + dy * cos,
                            },
                        ));
                    }
                    result.circles.push(SketchCircle {
                        id: name("circle"),
                        center: center.clone(),
                        rim: vertex.clone(),
                    });
                    let sides = (0..n)
                        .map(|k| name(&format!("side{k}")))
                        .collect::<Vec<_>>();
                    for k in 0..n {
                        result.lines.push(line(
                            sides[k].clone(),
                            &vertices[k],
                            &vertices[(k + 1) % n],
                        ));
                    }
                    // n − 1 vertices on the circle and n − 1 sides equal to
                    // the first: 2(n − 1) equations for 2(n − 1) unknowns.
                    for k in 1..n {
                        result.constraints.extend([
                            SketchConstraint::PointOnCurve {
                                point: vertices[k].clone(),
                                curve: name("circle"),
                            },
                            SketchConstraint::EqualLength {
                                first: sides[k].clone(),
                                second: sides[0].clone(),
                            },
                        ]);
                    }
                }
            }
        }
        let boundaries = self
            .shapes
            .iter()
            .map(|shape| (shape.id(), shape.boundary()))
            .collect::<HashMap<_, _>>();
        let expand = |ids: &[String]| -> Vec<String> {
            ids.iter()
                .flat_map(|id| {
                    boundaries
                        .get(id.as_str())
                        .cloned()
                        .unwrap_or_else(|| vec![id.clone()])
                })
                .collect()
        };
        result.profile = expand(&self.profile);
        result.holes = self.holes.iter().map(|hole| expand(hole)).collect();
        Ok(result)
    }
}
